type Config struct { Name string `json:"name"`; Workers int `json:"workers"` }
func decodeConfig(text string) (Config, error) {
    var config Config
    decoder := json.NewDecoder(strings.NewReader(text))
    decoder.DisallowUnknownFields()
    if err := decoder.Decode(&config); err != nil { return Config{}, err }
    var extra any
    if err := decoder.Decode(&extra); err != io.EOF { return Config{}, fmt.Errorf("expected one JSON value") }
    if strings.TrimSpace(config.Name) == "" || config.Workers < 1 || config.Workers > 8 { return Config{}, fmt.Errorf("invalid config") }
    return config, nil
}

func encodeMetric(name string, value float64) ([]byte, error) {
    if name == "" || math.IsNaN(value) || math.IsInf(value, 0) { return nil, fmt.Errorf("invalid metric") }
    return json.Marshal(struct { Name string `json:"name"`; Value float64 `json:"value"` }{name, value})
}

func greet(w http.ResponseWriter, r *http.Request) {
    if r.URL.Path != "/hello" { http.NotFound(w, r); return }
    if r.Method != http.MethodGet { w.Header().Set("Allow", "GET"); http.Error(w, "method", http.StatusMethodNotAllowed); return }
    name := strings.TrimSpace(r.URL.Query().Get("name"))
    if name == "" { http.Error(w, "name required", http.StatusBadRequest); return }
    w.Header().Set("Content-Type", "text/plain; charset=utf-8")
    fmt.Fprintf(w, "Hello, %s!", name)
}

func health(w http.ResponseWriter, r *http.Request) {
    if r.Method != http.MethodGet { http.Error(w, "method", 405); return }
    w.Header().Set("Content-Type", "application/json")
    io.WriteString(w, "{\"ok\":true}")
}
func TestHealth(t *testing.T) {
    for _, method := range []string{"GET", "POST"} {
        recorder := httptest.NewRecorder()
        health(recorder, httptest.NewRequest(method, "/", nil))
        response := recorder.Result()
        body, err := io.ReadAll(response.Body)
        response.Body.Close()
        if err != nil { t.Fatal(err) }
        if method == "GET" {
            if response.StatusCode != 200 || string(body) != "{\"ok\":true}" || response.Header.Get("Content-Type") != "application/json" { t.Fatal(response.StatusCode, string(body)) }
        } else if response.StatusCode != 405 { t.Fatal(response.StatusCode) }
    }
}

func receiveJob(ctx context.Context, jobs <-chan string) (string, error) {
    if err := ctx.Err(); err != nil { return "", err }
    select {
    case <-ctx.Done(): return "", ctx.Err()
    case job, ok := <-jobs:
        if !ok { return "", fmt.Errorf("jobs closed") }
        return job, nil
    }
}

func withinBudget(parent context.Context, budget time.Duration, work func(context.Context) error) error {
    if budget <= 0 { return fmt.Errorf("positive budget required") }
    ctx, cancel := context.WithTimeout(parent, budget)
    defer cancel()
    if err := ctx.Err(); err != nil { return err }
    return work(ctx)
}

type Counter struct { mu sync.Mutex; value int }
func (c *Counter) Add(delta int) error {
    if delta < 0 { return fmt.Errorf("negative increment") }
    c.mu.Lock()
    defer c.mu.Unlock()
    c.value += delta
    return nil
}
func (c *Counter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.value
}

func doubleAll(values []int) ([]int, error) {
    for _, value := range values { if value < 0 || value > 1000 { return nil, fmt.Errorf("value out of range") } }
    results := make([]int, len(values))
    var wg sync.WaitGroup
    for index, value := range values {
        wg.Add(1)
        go func(i, v int) { defer wg.Done(); results[i] = v * 2 }(index, value)
    }
    wg.Wait()
    return results, nil
}

func readLines(path string) ([]string, error) {
    file, err := os.Open(path)
    if err != nil { return nil, err }
    defer file.Close()
    lines := []string{}
    scanner := bufio.NewScanner(file)
    for scanner.Scan() { if text := strings.TrimSpace(scanner.Text()); text != "" { lines = append(lines, text) } }
    if err := scanner.Err(); err != nil { return nil, err }
    return lines, nil
}

func writeReport(path, text string) error {
    file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
    if err != nil { return err }
    _, writeErr := io.WriteString(file, text)
    closeErr := file.Close()
    if writeErr != nil { return writeErr }
    return closeErr
}
